import numpy as np
from collections import deque

def find_enclosed_regions(grid, bgc, bsc, fill_color):
    """Find all background pixels that are NOT connected to the grid boundary."""
    h, w = len(grid), len(grid[0])

    # Create a mask of background pixels (not border color)
    interior_mask = [[grid[i][j] == bgc for j in range(w)] for i in range(h)]

    # Find all background pixels connected to boundary
    q = deque()
    connected_to_boundary = [[False]*w for _ in range(h)]

    # Add all boundary background pixels to queue
    for i in range(h):
        for j in [0, w-1]:
            if interior_mask[i][j]:
                q.append((i, j))
                connected_to_boundary[i][j] = True

    for j in range(w):
        for i in [0, h-1]:
            if interior_mask[i][j]:
                q.append((i, j))
                connected_to_boundary[i][j] = True

    while q:
        i, j = q.popleft()
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < h and 0 <= nj < w:
                if interior_mask[ni][nj] and not connected_to_boundary[ni][nj]:
                    connected_to_boundary[ni][nj] = True
                    q.append((ni, nj))

    # Enclosed = background pixels NOT connected to boundary
    result = []
    for i in range(h):
        row = []
        for j in range(w):
            if interior_mask[i][j] and not connected_to_boundary[i][j]:
                row.append(fill_color)
            else:
                row.append(grid[i][j])
        result.append(row)
    return result

